head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[accordion > P > collapseAll]<br/>Accordion 컴포넌트의 초기 렌더링 시 모든 패널을 닫힌 상태로 시작할지 설정합니다.",
    "validation" : [
        "collapseAll=true 설정 시 초기 렌더링에서 모든 패널이 닫힌 상태로 렌더링됩니다.",
        "collapseAll=true 이면 unCollapseAll 속성은 무시되어 패널이 모두 열리지 않습니다.",
        "collapseAll=true 이면 selectedPanel 속성은 무시되어 지정한 패널이 열리지 않습니다.",
        "collapseAll=false (default) 설정 시 패널의 초기 열림/닫힘 상태가 unCollapseAll, selectedPanel 속성에 의해 결정됩니다.",
        "collapseAll=false (default) 이고 selectedPanel 속성을 설정하지 않으면 첫 번째 비활성화(disabled)되지 않은 패널만 열린 상태로 렌더링됩니다.",
        "collapseAll 속성은 초기화 시점 전용 속성이므로, collapseAll=true 로 모든 패널이 닫힌 이후 사용자 클릭에 의한 패널 토글 가능 여부는 collapsible 속성이 결정합니다.",
        "collapseAll=true, collapsible=true 환경에서 사용자가 패널 타이틀을 클릭하면 닫힌 패널이 열리거나 열린 패널이 닫히는 토글이 수행됩니다.",
        "collapseAll=true, collapsible=false 환경에서 사용자가 닫힌 패널 타이틀을 클릭하면 해당 패널이 열리지만, 열린 패널 타이틀 재클릭으로는 닫히지 않습니다.",
        "collapseAll 속성을 생략하면 기본값 false 로 동작합니다.",
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target 있으면 삭제
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    // 조건 설정
    let properties = {
        collapseAll : con_collapseAll.getText(),
        unCollapseAll : con_unCollapseAll.getText(),
        selectedPanel : con_selectedPanel.getValue(),
        collapsible : con_collapsible.getText(),
    };

    let cList = $c.gcm.createCList(properties);

    let grp_comp = $c.gcm.getTestGroup();
    let strTarget = '';
    let strNameSpace = $c.gcm.getNameSpace();

    $c.gcm.createLabel('label="* collapseAll=true 일 때 모든 패널이 닫힌 상태로 렌더링되는지 확인"', '', 'label1');
    $c.gcm.createLabel('label="* collapseAll=true + unCollapseAll=true / selectedPanel=panels2 옵션을 함께 설정해 무시되는지 확인"', '', 'label2');
    $c.gcm.createLabel('label="* collapseAll=false (default) + selectedPanel 미설정 시 첫 번째 패널만 열리는지 확인"', '', 'label3');
    $c.gcm.createLabel('label="* collapseAll=true 이후 패널 타이틀 클릭 시 토글 가능 여부는 collapsible 속성이 결정 (collapsible=true 토글 가능, false 닫기 불가)"', '', 'label4');

    strTarget += '<w2:accordion ' + strNameSpace + ' ' + cList + ' id="" style="width:240px; height:320px;">';
    strTarget += '<w2:panels style="" id="panels1" class="">';
    strTarget += '<w2:panelTitle style="" id="panelTitle1" label="panelTitle1"></w2:panelTitle>';
    strTarget += '<w2:panelContent style="" id="panelContent1">';
    strTarget += '<w2:button style="width:80px; height:23px;" id="" label="panel1"></w2:button>';
    strTarget += '</w2:panelContent>';
    strTarget += '</w2:panels>';
    strTarget += '<w2:panels style="" id="panels2" class="">';
    strTarget += '<w2:panelTitle style="" id="panelTitle2" label="panelTitle2"></w2:panelTitle>';
    strTarget += '<w2:panelContent style="" id="panelContent2">';
    strTarget += '<w2:button style="width:80px; height:23px;" id="" label="panel2"></w2:button>';
    strTarget += '</w2:panelContent>';
    strTarget += '</w2:panels>';
    strTarget += '<w2:panels style="" id="panels3" class="">';
    strTarget += '<w2:panelTitle style="" id="panelTitle3" label="panelTitle3"></w2:panelTitle>';
    strTarget += '<w2:panelContent style="" id="panelContent3">';
    strTarget += '<w2:button style="width:80px; height:23px;" id="" label="panel3"></w2:button>';
    strTarget += '</w2:panelContent>';
    strTarget += '</w2:panels>';
    strTarget += '</w2:accordion>';

    scwin.target1 = await $p.dynamicCreate(
        "target1",
        "accordion",
        strTarget,
        grp_comp
    );
}



// 현재 열린 패널 정보 출력 (getOpenPanelInfo)
scwin.btn_getOpenPanel_onclick = function (e) {
    wf_body_bottom.getObj("scwin").setReturnValue("===== getOpenPanelInfo() 결과 =====");
    let info = target1.getOpenPanelInfo();
    if (info && info.id) {
        wf_body_bottom.getObj("scwin").setReturnValue("열린 패널 id : " + info.id);
    } else {
        wf_body_bottom.getObj("scwin").setReturnValue("열린 패널 없음 (모두 닫힘)");
    }
};
